package com.rpsbattle.tournament;
import com.rpsbattle.account.*;import com.rpsbattle.account.domain.*;import com.rpsbattle.auth.*;import com.rpsbattle.bot.ownership.*;import com.rpsbattle.bot.upload.*;import com.rpsbattle.history.*;import com.rpsbattle.tournament.domain.*;import com.rpsbattle.tournament.persistence.*;import com.rpsbattle.tournament.ranking.*;import com.rpsbattle.tournament.registry.*;import com.rpsbattle.tournament.scheduler.*;
import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class TeamTournamentTest {
 @Test void teamWithNoEligibleMemberCannotRetainChampionThroughOldFixturePoints(){var t=cup();lock(t);for(var m:t.matches)TournamentFixtures.finish(m,m.participantA.participantId(),8,1);t.status=TournamentStatus.FINISHED;String winner=TeamScheduler.winner(t);assertThat(winner).isNotNull();var team=t.teams.teams().stream().filter(x->x.id().equals(winner)).findFirst().orElseThrow();for(var id:team.roster())t.operations=t.operations.participant(id,ParticipantStatus.DISQUALIFIED);assertThat(TeamScheduler.winner(t)).isNull();assertThat(TeamScheduler.view(t).get("champion")).isNull();assertThat(TeamScheduler.standings(t).getLast().get("id")).isEqualTo(winner);}
 @Test void lastMemberCanLeaveAnUnstartedTeamWithoutBlockingTheWholeTournament(){var t=cup();var team=t.teams.teams().getFirst();for(var id:team.roster())teams.join(aa,t.id,t.revision,team.id(),id,true);assertThat(t.teams.teams()).hasSize(1);assertThat(t.operations.audit().getLast().type()).isEqualTo("TEAM_REMOVED");assertThat(t.participants).hasSize(6);}
 @Test void disqualifiedRosterSlotIsForfeitedWithoutBlockingLineupSubmissionOrCreatingFakeReplay(){var t=cup();new TeamScheduler().schedule(t);t.status=TournamentStatus.RUNNING;var f=t.teams.fixtures().getFirst();var removed=t.teams.teams().getFirst().roster().getFirst();t.operations=t.operations.participant(removed,ParticipantStatus.DISQUALIFIED);for(var team:t.teams.teams())teams.lineup(team.captain().equals(a.id().value())?aa:bb,t.id,t.revision,f.id(),team.id(),team.roster());TeamScheduler.advance(t);assertThat(TournamentAdministrationService.settleForfeits(t)).isTrue();var forfeited=t.matches.stream().filter(m->m.status==TournamentMatch.Status.FINISHED).findFirst().orElseThrow();assertThat(forfeited.historyMatchId).isNull();assertThat(forfeited.winnerParticipantId).isNotEqualTo(removed);for(var m:t.matches)if(m.status==TournamentMatch.Status.PENDING)TournamentFixtures.finish(m,m.participantA.participantId(),8,1);assertThat(TeamScheduler.complete(t)).isTrue();}
 @Test void threeTeamsCannotLockFutureRoundBeforeAllPreviousFixturesFinish(){var t=cup();for(int i=0;i<3;i++)t.participants.add(new TournamentParticipant(UUID.randomUUID().toString(),UUID.randomUUID().toString(),"unused","C"+i,i,b.id().value()));teams.create(bb,t.id,t.revision,"C","School C",t.participants.get(6).participantId());var c=t.teams.teams().getLast();teams.join(bb,t.id,t.revision,c.id(),t.participants.get(7).participantId(),false);teams.join(bb,t.id,t.revision,c.id(),t.participants.get(8).participantId(),false);new TeamScheduler().schedule(t);t.status=TournamentStatus.RUNNING;for(var f:List.copyOf(t.teams.fixtures()))for(var team:t.teams.teams())if(Set.of(f.teamA(),f.teamB()).contains(team.id()))teams.lineup(team.captain().equals(a.id().value())?aa:bb,t.id,t.revision,f.id(),team.id(),team.roster());for(int round=1;round<=3;round++){assertThat(TeamScheduler.advance(t)).isTrue();assertThat(t.matches).hasSize(round*3);assertThat(TeamScheduler.advance(t)).isFalse();final int current=round;assertThat(t.matches.stream().filter(m->m.status==TournamentMatch.Status.PENDING)).allMatch(m->m.round==current);for(var m:t.matches)if(m.status==TournamentMatch.Status.PENDING)TournamentFixtures.finish(m,m.participantA.participantId(),8,1);}assertThat(TeamScheduler.complete(t)).isTrue();assertThat(t.teams.fixtures()).hasSize(3);}
 final TournamentRegistry registry=new TournamentRegistry();final BotUploadService bots=mock(BotUploadService.class);final TournamentRepository repository=mock(TournamentRepository.class);final TournamentService tournaments=new TournamentService(registry,bots,new FormatTournamentScheduler(),new RankingService(new ClassicScoringRule()));final AccountAuthorizationService accounts=mock(AccountAuthorizationService.class);final TournamentPersistenceCoordinator persistence=new TournamentPersistenceCoordinator(repository,registry,tournaments,mock(MatchPersistenceCoordinator.class),bots);final OwnedTournamentService owned=new OwnedTournamentService(tournaments,registry,persistence,accounts,new TournamentAuthorizationService(accounts),mock(OwnedBotService.class));final TeamTournamentService teams=new TeamTournamentService(tournaments,owned,accounts);
 final User a=user("A"),b=user("B");final org.springframework.security.core.Authentication aa=AuthService.sessionAuthentication(a),bb=AuthService.sessionAuthentication(b);
 User user(String name){return new User(UserId.random(),name,name+"@example.com","unused",name,UserRole.USER,AccountStatus.ACTIVE,Instant.EPOCH,Instant.EPOCH,null);}
 TeamTournamentTest(){when(accounts.requireUser(aa)).thenReturn(a);when(accounts.requireUser(bb)).thenReturn(b);}
 Tournament cup(){var t=registry.create("Teams",TournamentFormat.TEAM_ROUND_ROBIN);t.ownerUserId=a.id().value();t.status=TournamentStatus.REGISTRATION;for(int i=0;i<6;i++)t.participants.add(new TournamentParticipant(UUID.randomUUID().toString(),UUID.randomUUID().toString(),"unused","P"+i,i,i<3?a.id().value():b.id().value()));teams.create(aa,t.id,t.revision,"A","School A",t.participants.get(0).participantId());teams.create(bb,t.id,t.revision,"B","School B",t.participants.get(3).participantId());for(int i=1;i<3;i++){teams.join(aa,t.id,t.revision,t.teams.teams().get(0).id(),t.participants.get(i).participantId(),false);teams.join(bb,t.id,t.revision,t.teams.teams().get(1).id(),t.participants.get(i+3).participantId(),false);}return t;}
 @Test void membersAndCaptainAreAccountOwnedAndAllRosterChangesUseRevision(){var t=cup();assertThatThrownBy(()->teams.join(aa,t.id,t.revision,t.teams.teams().getFirst().id(),t.participants.getLast().participantId(),false)).hasMessage("TEAM_MEMBER_NOT_OWNED");assertThatThrownBy(()->teams.join(aa,t.id,0L,t.teams.teams().getFirst().id(),t.participants.getFirst().participantId(),true)).hasMessage("STALE_TOURNAMENT_REVISION");assertThatThrownBy(()->teams.create(aa,t.id,t.revision,"Again",null,t.participants.getFirst().participantId())).hasMessage("TEAM_MEMBER_DUPLICATE");t.status=TournamentStatus.RUNNING;assertThatThrownBy(()->teams.join(aa,t.id,t.revision,t.teams.teams().getFirst().id(),t.participants.getFirst().participantId(),true)).hasMessage("TEAM_ROSTER_LOCKED");}
 @Test void captainSubmitsThreeUniqueOwnedRosterSlotsAndPublicViewHidesUnsealedLineups(){var t=cup();new TeamScheduler().schedule(t);t.status=TournamentStatus.RUNNING;var f=t.teams.fixtures().getFirst();var team=t.teams.teams().getFirst();assertThatThrownBy(()->teams.lineup(bb,t.id,t.revision,f.id(),team.id(),team.roster())).hasMessage("TEAM_CAPTAIN_REQUIRED");assertThatThrownBy(()->teams.lineup(aa,t.id,t.revision,f.id(),team.id(),List.of(team.roster().getFirst(),team.roster().getFirst(),team.roster().getLast()))).hasMessage("INVALID_TEAM_LINEUP");teams.lineup(aa,t.id,t.revision,f.id(),team.id(),team.roster());assertThat(TeamScheduler.advance(t)).isFalse();var publicFixture=(Map<?,?>)((List<?>)TeamScheduler.view(t).get("fixtures")).getFirst();assertThat((List<?>)publicFixture.get("lineupA")).isEmpty();assertThat((List<?>)publicFixture.get("lineupB")).isEmpty();assertThat(TeamScheduler.privateLineups(t,b.id().value()).values()).allSatisfy(ids->assertThat(ids).isEmpty());assertThat(TeamScheduler.privateLineups(t,a.id().value()).values()).contains(team.roster());}
 void lock(Tournament t){new TeamScheduler().schedule(t);t.status=TournamentStatus.RUNNING;var f=t.teams.fixtures().getFirst();for(var team:t.teams.teams())teams.lineup(team.captain().equals(a.id().value())?aa:bb,t.id,t.revision,f.id(),team.id(),team.roster());assertThat(TeamScheduler.advance(t)).isTrue();}
 @Test void lockedThreeBoardBo3FixtureScoresOnceAndCannotChangeLineup(){var t=cup();t.bestOf=3;lock(t);var f=t.teams.fixtures().getFirst();assertThat(t.matches).hasSize(3);assertThat(TeamScheduler.advance(t)).isFalse();assertThatThrownBy(()->teams.lineup(aa,t.id,t.revision,f.id(),t.teams.teams().getFirst().id(),t.teams.teams().getFirst().roster())).hasMessage("TEAM_LINEUP_LOCKED");for(int game=0;game<2;game++){for(var m:t.matches)if(m.status==TournamentMatch.Status.PENDING)TournamentFixtures.finish(m,m.participantA.participantId(),8,1);if(game==0){assertThat(TeamScheduler.score(t,f).complete()).isFalse();TournamentSeries.advance(t);}}assertThat(t.matches).hasSize(6);assertThat(TeamScheduler.score(t,f)).isEqualTo(new TeamScheduler.Score(true,6,0,false));assertThat(TeamScheduler.complete(t)).isTrue();assertThat(TeamScheduler.standings(t).getFirst()).containsEntry("points",3).containsEntry("played",1);}
 @Test void jsonRecoveryPreservesCaptainRosterFixtureAndLockedSlotIdentity(){var t=cup();lock(t);var converter=new TournamentDetailsConverter();var details=converter.convertToEntityAttribute(converter.convertToDatabaseColumn(TournamentDetails.snapshot(t)));var loaded=new Tournament(t.id,t.name,t.format,t.createdAt);loaded.participants.addAll(t.participants);t.matches.forEach(m->loaded.matches.add(m.copy()));details.restore(loaded);loaded.status=TournamentStatus.RUNNING;assertThat(loaded.teams).isEqualTo(t.teams);assertThat(TeamScheduler.advance(loaded)).isFalse();assertThat(loaded.matches).hasSize(3);}
 @Test void failedCommitRollsBackRosterAndLineupWithoutPublishingPartialMembership(){var t=cup();var before=t.teams;doThrow(new org.springframework.dao.DataAccessResourceFailureException("outage")).when(repository).save(any());assertThatThrownBy(()->teams.join(aa,t.id,t.revision,t.teams.teams().getFirst().id(),t.participants.getFirst().participantId(),true)).isInstanceOf(org.springframework.dao.DataAccessResourceFailureException.class);assertThat(t.teams).isEqualTo(before);}
 @Test void incompleteRostersCannotStartAndDoubleForfeitCreatesNoTeamChampion(){var t=cup();var before=t.teams;t.teams=TeamState.empty();assertThatThrownBy(()->new TeamScheduler().schedule(t)).hasMessage("TEAM_ROSTER_INCOMPLETE");t.teams=before;lock(t);for(var p:t.participants)t.operations=t.operations.participant(p.participantId(),ParticipantStatus.DISQUALIFIED);TournamentAdministrationService.settleForfeits(t);assertThat(TeamScheduler.complete(t)).isTrue();t.status=TournamentStatus.FINISHED;assertThat(TeamScheduler.view(t).get("champion")).isNull();assertThat(TeamScheduler.standings(t)).allSatisfy(row->assertThat(row).containsEntry("points",0));}
}
